marker-parser.fence:
parseMarkers(bytes, ext):
  form = conventions.markerComment[ext]        # no form -> the file cannot be marked: an error on the attempt
  text = decodeUtf8Strict(bytes)               # invalid UTF-8 -> error CK-E-ENCODING
  opened = stack; blocks = []; errors = []
  for every line i (split on \n; a \r at the end of a line -> error CK-E-CRLF):
    m = the line matches ^\s*<form.open>(begin|end)\s+(CK-[a-z]+-[0-9]{3})\s*<form.close>\s*$
        # form.open already ENDS with "codkit:" (the form of ##CONV-MARKER-FORMS) - the word is not duplicated
    if the line contains "codkit:begin"|"codkit:end" but m did not match -> error CK-E-MARKER-MALFORMED(i)
    if m.kind == begin:
      if the stack is not empty -> error CK-E-MARKER-NESTED(i)   # nesting is forbidden
      # an id already seen in the file opens one more block of the same intervention (##MR-SEVERAL-BLOCKS-ONE-ID)
      push {id, i}
    if m.kind == end:
      if the stack is empty or top.id != id -> CK-E-MARKER-UNBALANCED(i)
      blocks += {id, top.line, i}; pop
  if the stack is not empty -> CK-E-MARKER-UNCLOSED(top.line)
  an id that does not match idPattern -> CK-E-MARKER-BAD-ID
  return {blocks, errors}
